export const VILLES: Record<string, { x: number; y: number; nom: string }> = {
  maroua: { x: 285, y: 120.3, nom: "Maroua" },
  garoua: { x: 245.1, y: 177.2, nom: "Garoua" },
  ngaoundere: { x: 253.2, y: 263.8, nom: "Ngaoundéré" },
  bamenda: { x: 104.5, y: 323.4, nom: "Bamenda" },
  bafoussam: { x: 115.7, y: 344.6, nom: "Bafoussam" },
  buea: { x: 64.6, y: 402.2, nom: "Buéa" },
  douala: { x: 87.5, y: 406.7, nom: "Douala" },
  yaounde: { x: 162.8, y: 415.6, nom: "Yaoundé" },
  bertoua: { x: 257.6, y: 383.8, nom: "Bertoua" },
  ebolowa: { x: 147.5, y: 456.8, nom: "Ebolowa" },
  kribi: { x: 93.7, y: 455.2, nom: "Kribi" },
};

// Villes dont l'étiquette se place à gauche du point (évite les chevauchements sur le littoral).
const GAUCHE = new Set(["buea"]);

type Props = {
  className?: string;
  // "sombre" : silhouette claire sur fond bleu nuit ; "clair" : silhouette bleu nuit sur fond clair.
  variante?: "sombre" | "clair";
  points?: string[];
  etiquettes?: boolean;
  actif?: string | null;
};

export function CarteCameroun({ className, variante = "clair", points = [], etiquettes = false, actif = null }: Props) {
  const sombre = variante === "sombre";
  return (
    <svg viewBox={CARTE_VIEWBOX} className={className} role="img" aria-label="Carte du Cameroun">
      <path
        d={CARTE_CONTOUR}
        fill={sombre ? "rgba(255,255,255,0.10)" : "#0a2a5e"}
        stroke={sombre ? "rgba(255,255,255,0.55)" : "#0a2a5e"}
        strokeWidth={sombre ? 1.5 : 1}
        strokeLinejoin="round"
      />
      {points.map((cle) => {
        const v = VILLES[cle];
        if (!v) return null;
        const enAvant = actif === cle;
        return (
          <g key={cle}>
            <circle cx={v.x} cy={v.y} r={enAvant ? 16 : 11} fill="var(--color-gold-500)" opacity={0.28} />
            <circle cx={v.x} cy={v.y} r={enAvant ? 7 : 5} fill="var(--color-gold-500)" stroke="#fff" strokeWidth={1.5} />
            {etiquettes && (
              <text
                x={GAUCHE.has(cle) ? v.x - 9 : v.x + 9}
                y={v.y + 4}
                textAnchor={GAUCHE.has(cle) ? "end" : "start"}
                fontSize={13}
                fontWeight={600}
                fill={sombre ? "#fff" : "#00183d"}
                stroke={sombre ? "#00183d" : "#fff"}
                strokeWidth={3}
                paintOrder="stroke"
              >
                {v.nom}
              </text>
            )}
          </g>
        );
      })}
    </svg>
  );
}
